        if (!date.trim()) {
          setError('A date is required');
          return;
        }
        setError('');
        add.mutate(
          { amount: amountValue, date: date.trim() },
          {
            onSuccess: () => {
              setAmount('');
              setDate('');
            },
          },
        );
      }}
    >
