10	// driven through the form. Seed honours projects: { id, clientId, name }, invoices: { id, projectId,
11	// amount } and clients: { id, name, email }.
12	//
13	// Amounts are MONEY, asserted in the app's money format ("$250.00") per the money-format change.
14	import { test, expect } from '@playwright/test';
15	import { resetAndSeed } from '../support/seed';
16	
17	test.describe('invoice amount must be more than zero', () => {
